4	<meta charset="utf-8" />
5	<meta name="viewport" content="width=device-width, initial-scale=1" />
6	<title>Bookmarks — prototype</title>
7	<style>
8	  :root {
9	    --bg: #f6f7f9;
10	    --card: #ffffff;
11	    --line: #e4e7ec;
12	    --text: #1a1d23;
13	    --muted: #6b7280;
14	    --accent: #2563eb;
15	    --accent-soft: #eff4ff;
16	  }
17	  * { box-sizing: border-box; }
18	  body {
19	    margin: 0;
20	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
21	    background: var(--bg);
22	    color: var(--text);
23	  }
24	  header {
25	    background: var(--card);
26	    border-bottom: 1px solid var(--line);
27	    padding: 18px 24px;
28	  }
29	  header h1 { margin: 0; font-size: 20px; }
30	  header p { margin: 4px 0 0; color: var(--muted); font-size: 13px; }
31	  .wrap { max-width: 880px; margin: 0 auto; padding: 24px; }
