111	</head>
112	<body>
113	<header>
114	  <h1>My Bookmarks</h1>
115	  <p>Save a link, and it lands under its topic.</p>
116	</header>
117	
118	<div class="wrap">
119	  <div class="add-card">
120	    <div class="add-row">
121	      <div class="field">
122	        <label for="url">Link address</label>
123	        <input id="url" type="text" placeholder="https://…" />
124	      </div>
125	      <div class="field">
126	        <label for="title">Title</label>
127	        <input id="title" type="text" placeholder="What is this link?" />
128	      </div>
129	      <div class="field">
130	        <label for="topic">Topic</label>
131	        <input id="topic" type="text" placeholder="e.g. Design, Recipes" />
132	      </div>
133	      <button class="primary" id="save">Save link</button>
134	    </div>
135	  </div>
136	
137	  <div class="search-card">
138	    <input id="search" type="text" placeholder="Search your links by word, title or topic…" />
139	    <div id="search-meta" class="search-meta"></div>
140	  </div>
141	
142	  <div id="list"></div>
143	</div>
144	
145	<script>
146	  const seed = [
147	    { url: "https://www.smashingmagazine.com/", title: "Smashing Magazine", topic: "Design" },
148	    { url: "https://refactoring.guru/", title: "Refactoring Guru", topic: "Development" },
149	    { url: "https://www.bbcgoodfood.com/", title: "BBC Good Food", topic: "Recipes" },
150	  ];
151	  let bookmarks = JSON.parse(localStorage.getItem("bm") || "null") || seed.slice();
152	
153	  function persist() { localStorage.setItem("bm", JSON.stringify(bookmarks)); }
154	
155	  function render(flashId) {
156	    const list = document.getElementById("list");
157	    const meta = document.getElementById("search-meta");
158	    const q = document.getElementById("search").value.trim().toLowerCase();
159	    list.innerHTML = "";
160	    if (bookmarks.length === 0) {
161	      list.innerHTML = '<div class="empty">No links saved yet.<br>Add your first one above.</div>';
162	      meta.textContent = "";
163	      return;
164	    }
165	    let matches = bookmarks.map((b, i) => ({ ...b, i }));
166	    if (q) {
167	      matches = matches.filter(b =>
168	        (b.title || "").toLowerCase().includes(q) ||
169	        (b.url || "").toLowerCase().includes(q) ||
170	        (b.topic || "").toLowerCase().includes(q));
171	      meta.textContent = matches.length + (matches.length === 1 ? " link found" : " links found");
172	    } else {
173	      meta.textContent = "";
174	    }
175	    if (q && matches.length === 0) {
176	      list.innerHTML = '<div class="empty">No links match "' + escapeHtml(q) + '".<br>Try a different word.</div>';
177	      return;
178	    }
179	    const topics = {};
180	    matches.forEach(b => { (topics[b.topic || "Untitled topic"] ||= []).push(b); });
181	    Object.keys(topics).sort((a, b) => a.localeCompare(b)).forEach(topic => {
182	      const group = document.createElement("div");
183	      group.className = "topic-group";
184	      group.innerHTML = `<h2 class="topic-head">${escapeHtml(topic)} <span class="topic-count">${topics[topic].length}</span></h2>`;
185	      topics[topic].forEach(b => {
186	        const el = document.createElement("div");
187	        el.className = "bm" + (b.i === flashId ? " flash" : "");
188	        el.innerHTML = `<a href="${escapeAttr(b.url)}" target="_blank" rel="noopener">${highlight(b.title || b.url, q)}</a>
189	                        <div class="url">${highlight(b.url, q)}</div>`;
190	        group.appendChild(el);
191	      });
192	      list.appendChild(group);
193	    });
194	  }
195	
196	  function escapeHtml(s) { return (s || "").replace(/[&<>]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c])); }
197	  function escapeAttr(s) { return escapeHtml(s).replace(/"/g, "&quot;"); }
198	  function highlight(s, q) {
199	    const safe = escapeHtml(s || "");
200	    if (!q) return safe;
201	    const idx = safe.toLowerCase().indexOf(q.toLowerCase());
202	    if (idx === -1) return safe;
203	    return safe.slice(0, idx) + "<mark>" + safe.slice(idx, idx + q.length) + "</mark>" + safe.slice(idx + q.length);
204	  }
205	
206	  document.getElementById("save").addEventListener("click", () => {
207	    const url = document.getElementById("url").value.trim();
208	    const title = document.getElementById("title").value.trim();
209	    const topic = document.getElementById("topic").value.trim();
210	    if (!url) { document.getElementById("url").focus(); return; }
211	    bookmarks.push({ url, title, topic });
212	    persist();
213	    document.getElementById("url").value = "";
214	    document.getElementById("title").value = "";
215	    document.getElementById("topic").value = "";
216	    document.getElementById("url").focus();
217	    render(bookmarks.length - 1);
218	  });
219	
220	  document.getElementById("search").addEventListener("input", () => render());
221	
222	  render();
223	  document.body.setAttribute("data-harness-ready", "true");
224	</script>
225	</body>
226	</html>
